    13		"time"
    14	)
    15	
    16	type Service struct{ S *store.Store }
    17	
    18	func Token() string { b := make([]byte, 16); rand.Read(b); return hex.EncodeToString(b) }
    19	
    20	// MaxSeconds bounds every seconds-valued input so that now+seconds never
    21	// leaves time.Duration's range (about 292 years).
    22	const MaxSeconds = math.MaxInt32
    23	
    24	// DefaultMaxSeconds caps each retry wait of a queue without backoff.max_seconds.
    25	const DefaultMaxSeconds = 3600
    26	
    27	// Backoff is the wait before retry attempt+1. It saturates at the queue's cap
    28	// (maxSeconds > 0), or at DefaultMaxSeconds or the base if that is larger.
    29	func Backoff(kind string, base, attempt, maxSeconds int) time.Duration {
    30		limit := float64(max(DefaultMaxSeconds, base))
    31		if maxSeconds > 0 {
    32			limit = float64(maxSeconds)
    33		}
    34		steps := float64(attempt)
    35		if kind != "linear" {
    36			steps = math.Exp2(float64(attempt - 1))
    37		}
    38		return time.Duration(min(float64(base)*steps, limit) * float64(time.Second))
    39	}
    40	
    41	var ErrWorkerNotFound = errors.New("worker not found")
    42	
    43	const LeaseOrder = "priority DESC, created_at, id"
    44	
    45	func (j *Service) Lease(q, w int64, max int, now time.Time) ([]map[string]any, error) {
    46		tx, e := j.S.DB.Begin()
    47		if e != nil {
    48			return nil, e
    49		}
    50		defer tx.Rollback()
    51		var sec int
    52		var paused bool
    53		if e = tx.QueryRow(`SELECT lease_seconds,paused FROM queues WHERE id=$1`, q).Scan(&sec, &paused); e != nil {
    54			return nil, e
    55		}
    56		var kinds pq.StringArray
    57		if e = tx.QueryRow(`SELECT kinds FROM workers WHERE id=$1 FOR SHARE`, w).Scan(&kinds); e != nil {
    58			if e == sql.ErrNoRows {
    59				return nil, ErrWorkerNotFound
    60			}
    61			return nil, e
    62		}
    63		if paused {
    64			return []map[string]any{}, nil
    65		}
    66		rows, e := tx.Query(`SELECT id FROM jobs WHERE queue_id=$1 AND state='queued' AND kind=ANY($2) ORDER BY `+LeaseOrder+` LIMIT $3 FOR UPDATE SKIP LOCKED`, q, kinds, max)
    67		if e != nil {
    68			return nil, e
    69		}
    70		ids := []int64{}
    71		for rows.Next() {
    72			var id int64
    73			rows.Scan(&id)
    74			ids = append(ids, id)
    75		}
    76		rows.Close()
    77		out := []map[string]any{}
    78		for _, id := range ids {
    79			token := Token()
    80			var payload []byte
    81			var kind string
    82			var attempt int
    83			e = tx.QueryRow(`UPDATE jobs SET state='leased',leased_at=$5,event_at=$5,leased_by=$2,lease_token=$3,lease_expires_at=$4 WHERE id=$1 RETURNING kind,payload,attempts+1`, id, w, token, now.Add(time.Duration(sec)*time.Second), now).Scan(&kind, &payload, &attempt)
    84			if e != nil {
    85				return nil, e
    86			}
    87			out = append(out, map[string]any{"id": id, "kind": kind, "payload": json.RawMessage(payload), "attempt": attempt, "lease_token": token, "lease_expires_at": now.Add(time.Duration(sec) * time.Second)})
    88		}
    89		return out, tx.Commit()
    90	}
    91	func (j *Service) Notify(id int64, now time.Time) error {
    92		var url, secret, state, errtext string
    93		var result []byte
    94		e := j.S.DB.QueryRow(`SELECT q.webhook_url,q.webhook_secret,j.state,COALESCE(j.result,'null'),j.last_error FROM jobs j JOIN queues q ON q.id=j.queue_id WHERE j.id=$1`, id).Scan(&url, &secret, &state, &result, &errtext)
    95		if e != nil {
    96			return e
    97		}
    98		if url == "" {
    99			return nil
   100		}
   101		body, _ := json.Marshal(map[string]any{"job_id": id, "state": state, "result": json.RawMessage(result), "last_error": errtext})
   102		_, e = j.S.DB.Exec(`INSERT INTO webhook_outbox(job_id,url,secret,body,next_at,event_at,namespace_id,queue) SELECT $1,$2,$3,$4,$5,$5,j.namespace_id,q.name FROM jobs j JOIN queues q ON q.id=j.queue_id WHERE j.id=$1`, id, url, secret, string(body), now)
   103		return e
   104	}
   105	func (j *Service) Heartbeat(id int64, token string, seconds int, now time.Time) error {
   106		r, e := j.S.DB.Exec(`UPDATE jobs SET lease_expires_at=$3,event_at=$4 WHERE id=$1 AND lease_token=$2 AND state='leased' AND lease_expires_at > $4`, id, token, now.Add(time.Duration(seconds)*time.Second), now)
   107		return Changed(r, e)
   108	}
   109	func Changed(r sql.Result, e error) error {
   110		if e != nil {
   111			return e
   112		}
   113		n, e := r.RowsAffected()
   114		if e != nil {
   115			return e
   116		}
   117		if n == 0 {
   118			return fmt.Errorf("state conflict")
   119		}
   120		return nil
   121	}
