    10	func (j *Service) Ack(id int64, token string, result any, now time.Time) error {
    11		b, _ := json.Marshal(result)
    12		// The joined row is the pre-update snapshot: it still names the holder.
    13		var worker int64
    14		e := j.S.DB.QueryRow(`UPDATE jobs j SET state='succeeded',event_at=$3,result=$2,finished_at=$3,attempts=j.attempts+1,lease_token=NULL,leased_by=NULL,lease_expires_at=NULL FROM jobs o WHERE o.id=j.id AND j.id=$1 AND j.state='leased' AND j.lease_token=$4 AND j.lease_expires_at > $3 RETURNING o.leased_by`, id, string(b), now, token).Scan(&worker)
    15		if e == sql.ErrNoRows {
    16			return fmt.Errorf("state conflict")
    17		}
    18		if e != nil {
    19			return e
    20		}
    21		_, e = j.S.DB.Exec(`INSERT INTO attempts SELECT id,(SELECT count(*)+1 FROM attempts WHERE job_id=$1),$3,leased_at,$2,'succeeded','' FROM jobs WHERE id=$1`, id, now, worker)
    22		if e != nil {
    23			return e
    24		}
    25		return j.Notify(id, now)
    26	}
