     1	package jobs
     2	
     3	import "time"
     4	
     5	func (j *Service) Nack(id int64, token, message string, retry bool, delay *int, now time.Time) error {
     6		tx, e := j.S.DB.Begin()
     7		if e != nil {
     8			return e
     9		}
    10		defer tx.Rollback()
    11		var attempts, max, base, cap int
    12		var kind string
    13		var purged bool
    14		var worker int64
    15		e = tx.QueryRow(`SELECT j.attempts+1,j.max_attempts,q.backoff_kind,q.backoff_base,COALESCE(q.backoff_max,0),j.leased_by,j.purge_requested FROM jobs j JOIN queues q ON q.id=j.queue_id WHERE j.id=$1 AND j.state='leased' AND j.lease_token=$2 AND j.lease_expires_at > $3 FOR UPDATE OF j`, id, token, now).Scan(&attempts, &max, &kind, &base, &cap, &worker, &purged)
    16		if e != nil {
    17			return e
    18		}
    19		state := "retry_wait"
    20		if !retry || attempts >= max || purged {
    21			state = "dead"
    22		}
    23		wait := Backoff(kind, base, attempts, cap)
    24		if delay != nil {
    25			wait = time.Duration(*delay) * time.Second
    26		}
    27		_, e = tx.Exec(`UPDATE jobs SET state=$2,event_at=$6,attempts=$3,last_error=$4,run_at=$5,finished_at=CASE WHEN $2='dead' THEN $6::timestamptz ELSE NULL END,lease_token=NULL,leased_by=NULL,lease_expires_at=NULL WHERE id=$1`, id, state, attempts, message, now.Add(wait), now)
    28		if e != nil {
    29			return e
    30		}
    31		_, e = tx.Exec(`INSERT INTO attempts SELECT $1,(SELECT count(*)+1 FROM attempts WHERE job_id=$1),$2,leased_at,$3,'failed',$4 FROM jobs WHERE id=$1`, id, worker, now, message)
    32		if e != nil {
    33			return e
    34		}
    35		if e = tx.Commit(); e != nil {
    36			return e
    37		}
    38		if state == "dead" {
    39			return j.Notify(id, now)
    40		}
    41		return nil
    42	}
