     1	package jobs
     2	
     3	import (
     4		"database/sql"
     5		"time"
     6	)
     7	
     8	func (j *Service) Expire(now time.Time) error {
     9	
    10		tx, e := j.S.DB.Begin()
    11		if e != nil {
    12			return e
    13		}
    14		defer tx.Rollback()
    15		// The event trigger labels this transaction's releases as expiries.
    16		if _, e = tx.Exec(`SET LOCAL queuelet.release='lease_expired'`); e != nil {
    17			return e
    18		}
    19		dead, e := release(tx, now, "expired", "lease expired", `state='leased' AND lease_expires_at <= $1 ORDER BY id FOR UPDATE SKIP LOCKED`, now)
    20		if e != nil {
    21			return e
    22		}
    23		if e = tx.Commit(); e != nil {
    24			return e
    25		}
    26		for _, id := range dead {
    27			if e = j.Notify(id, now); e != nil {
    28				return e
    29			}
    30		}
    31		return nil
    32	}
    33	
    34	// ReleaseWorker ends a deregistered worker's leases inside the caller's
    35	// transaction. The caller notifies the returned dead jobs after commit.
    36	func (j *Service) ReleaseWorker(tx *sql.Tx, worker int64, now time.Time) ([]int64, error) {
    37		return release(tx, now, "released", "worker deleted", `state='leased' AND leased_by=$1 ORDER BY id FOR UPDATE`, worker)
    38	}
    39	
    40	// release ends the selected leases. Each records an unsuccessful attempt; the
    41	// job is queued again, or dead when its attempts are spent or its queue was
    42	// purged while it ran.
    43	func release(tx *sql.Tx, now time.Time, outcome, reason, where string, arg any) ([]int64, error) {
    44		rows, e := tx.Query(`SELECT id,attempts+1,max_attempts,leased_by,purge_requested FROM jobs WHERE `+where, arg)
    45		if e != nil {
    46			return nil, e
    47		}
    48		type expired struct {
    49			id, worker int64
    50			n, max     int
    51			purged     bool
    52		}
    53		batch := []expired{}
    54		for rows.Next() {
    55			var r expired
    56			if e = rows.Scan(&r.id, &r.n, &r.max, &r.worker, &r.purged); e != nil {
    57				rows.Close()
    58				return nil, e
    59			}
    60			batch = append(batch, r)
    61		}
    62		e = rows.Err()
    63		rows.Close()
    64		if e != nil {
    65			return nil, e
    66		}
    67		dead := []int64{}
    68		for _, r := range batch {
    69			state := "queued"
    70			if r.n >= r.max || r.purged {
    71				state = "dead"
    72				dead = append(dead, r.id)
    73			}
    74			_, e = tx.Exec(`UPDATE jobs SET state=$2,event_at=$4,attempts=$3,last_error=$5,run_at=$4,lease_token=NULL,leased_by=NULL,lease_expires_at=NULL,finished_at=CASE WHEN $2='dead' THEN $4::timestamptz ELSE NULL END WHERE id=$1`, r.id, state, r.n, now, reason)
    75			if e != nil {
    76				return nil, e
    77			}
    78			_, e = tx.Exec(`INSERT INTO attempts SELECT $1,(SELECT count(*)+1 FROM attempts WHERE job_id=$1),$2,leased_at,$3,$4,$5 FROM jobs WHERE id=$1`, r.id, r.worker, now, outcome, reason)
    79			if e != nil {
    80				return nil, e
    81			}
    82		}
    83		return dead, nil
    84	}
    85	
    86	func (j *Service) Promote(now time.Time) error {
    87		_, e := j.S.DB.Exec(`UPDATE jobs SET state='queued',event_at=$1 WHERE state IN ('scheduled','retry_wait') AND run_at <= $1`, now)
    88		return e
    89	}
    90	func (j *Service) Retain(now time.Time) error {
    91		_, e := j.S.DB.Exec(`WITH removed AS (DELETE FROM jobs j USING queues q WHERE j.queue_id=q.id AND j.state IN ('succeeded','cancelled') AND extract(epoch FROM $1::timestamptz - j.finished_at) / 3600 > q.retention_hours RETURNING j.*) INSERT INTO job_events(job_id,namespace_id,at,event,queue,worker,attempt) SELECT r.id,r.namespace_id,$1,'retained',q.name,r.leased_by,r.attempts FROM removed r JOIN queues q ON q.id=r.queue_id`, now)
    92		return e
    93	}
