     1	package jobs
     2	
     3	import (
     4		"crypto/sha256"
     5		"database/sql"
     6		"encoding/hex"
     7		"fmt"
     8		"time"
     9	)
    10	
    11	func (j *Service) Cancel(id int64, now time.Time) error {
    12		tx, e := j.S.DB.Begin()
    13		if e != nil {
    14			return e
    15		}
    16		defer tx.Rollback()
    17		var state string
    18		e = tx.QueryRow(`SELECT state FROM jobs WHERE id=$1 AND state NOT IN ('succeeded','dead','cancelled') FOR UPDATE`, id).Scan(&state)
    19		if e == sql.ErrNoRows {
    20			return fmt.Errorf("state conflict")
    21		}
    22		if e != nil {
    23			return e
    24		}
    25		if state == "leased" {
    26			_, e = tx.Exec(`INSERT INTO attempts SELECT id,(SELECT count(*)+1 FROM attempts WHERE job_id=$1),leased_by,leased_at,$2,'cancelled','operator cancelled' FROM jobs WHERE id=$1`, id, now)
    27			if e != nil {
    28				return e
    29			}
    30		}
    31		_, e = tx.Exec(`UPDATE jobs SET state='cancelled',event_at=$2,finished_at=$2,attempts=attempts+CASE WHEN state='leased' THEN 1 ELSE 0 END,cancelled_lease_hash=encode(sha256(lease_token::bytea),'hex'),lease_token=NULL,leased_by=NULL,lease_expires_at=NULL WHERE id=$1`, id, now)
    32		if e != nil {
    33			return e
    34		}
    35		if e = tx.Commit(); e != nil {
    36			return e
    37		}
    38		return j.Notify(id, now)
    39	}
    40	
    41	// CancelRequested is an observation, never an extension of the revoked lease.
    42	func (j *Service) CancelRequested(id int64, token string) (bool, error) {
    43		var requested bool
    44		digest := sha256.Sum256([]byte(token))
    45		e := j.S.DB.QueryRow(`SELECT EXISTS(SELECT 1 FROM jobs WHERE id=$1 AND state='cancelled' AND cancelled_lease_hash=$2)`, id, hex.EncodeToString(digest[:])).Scan(&requested)
    46		return requested, e
    47	}
    48	
    49	func (j *Service) Retry(id int64, now time.Time) error {
    50		r, e := j.S.DB.Exec(`UPDATE jobs SET state='queued',event_at=$2,attempts=0,run_at=$2,finished_at=NULL,purge_requested=false WHERE id=$1 AND state='dead'`, id, now)
    51		return Changed(r, e)
    52	}
=== internal/jobs/purge.go
     1	package jobs
     2	
     3	import (
     4		"github.com/lib/pq"
     5		"time"
     6	)
     7	
     8	func (j *Service) Purge(queue int64, now time.Time) (int64, error) {
     9		tx, err := j.S.DB.Begin()
    10		if err != nil {
    11			return 0, err
    12		}
    13		defer tx.Rollback()
    14		// Lock every pending or leased row first. A row that moves between pending
    15		// and leased while we wait still matches, and the statements below see its
    16		// committed state. No queue/global lock is needed. ReleaseWorker also locks
    17		// in id order; Lease and Expire skip locked jobs.
    18		rows, err := tx.Query(`SELECT id FROM jobs WHERE queue_id=$1 AND state IN ('queued','scheduled','retry_wait','leased') ORDER BY id FOR UPDATE`, queue)
    19		if err != nil {
    20			return 0, err
    21		}
    22		ids := []int64{}
    23		for rows.Next() {
    24			var id int64
    25			if err = rows.Scan(&id); err != nil {
    26				rows.Close()
    27				return 0, err
    28			}
    29			ids = append(ids, id)
    30		}
    31		err = rows.Err()
    32		rows.Close()
    33		if err != nil {
    34			return 0, err
    35		}
    36		// Restrict both writes to the locked snapshot: concurrently inserted jobs
    37		// may legitimately belong after this purge. Capture the boundary via ids.
    38		if _, err = tx.Exec(`UPDATE jobs SET purge_requested=true WHERE id=ANY($1) AND state='leased'`, pq.Array(ids)); err != nil {
    39			return 0, err
    40		}
    41		res, err := tx.Exec(`WITH removed AS (DELETE FROM jobs WHERE id=ANY($1) AND state IN ('queued','scheduled','retry_wait') RETURNING *) INSERT INTO job_events(job_id,namespace_id,at,event,queue,worker,attempt) SELECT r.id,r.namespace_id,$2,'purged',q.name,r.leased_by,r.attempts FROM removed r JOIN queues q ON q.id=r.queue_id`, pq.Array(ids), now)
    42		if err != nil {
    43			return 0, err
    44		}
    45		n, err := res.RowsAffected()
    46		if err != nil {
    47			return 0, err
    48		}
    49		return n, tx.Commit()
    50	}

