     1	package schedule
     2	
     3	import (
     4		"database/sql"
     5		"fmt"
     6		"github.com/robfig/cron/v3"
     7		"queuelet/internal/store"
     8		"strings"
     9		"time"
    10	)
    11	
    12	var parser = cron.NewParser(cron.Minute | cron.Hour | cron.Dom | cron.Month | cron.Dow)
    13	
    14	func Next(expression, zone string, offset int, after time.Time) (time.Time, error) {
    15		s, e := parser.Parse(expression)
    16		if e != nil {
    17			return time.Time{}, e
    18		}
    19		loc, e := time.LoadLocation(zone)
    20		if e != nil {
    21			return time.Time{}, e
    22		}
    23		if strings.HasPrefix(strings.Fields(expression)[1], "*") {
    24			// Wildcard hours follow elapsed time across offset changes.
    25			return s.Next(after.In(loc)), nil
    26		}
    27		// Fixed hours match local civil times: a time skipped by a transition runs once
    28		// at the end of the gap, and a repeated time runs at its first occurrence only.
    29		l := after.In(loc)
    30		wall := time.Date(l.Year(), l.Month(), l.Day(), l.Hour(), l.Minute(), l.Second(), l.Nanosecond(), time.UTC)
    31		for range 1500 {
    32			if wall = s.Next(wall); wall.IsZero() {
    33				return wall, nil
    34			}
    35			if t := civil(wall, loc); t.After(after) {
    36				return t, nil
    37			}
    38		}
    39		return time.Time{}, fmt.Errorf("schedule cannot advance")
    40	}
    41	
    42	// civil returns the first instant at which loc shows the wall-clock time carried in
    43	// wall's UTC fields, or the end of the gap when a transition skips that time.
    44	func civil(wall time.Time, loc *time.Location) time.Time {
    45		var first time.Time
    46		for _, probe := range []time.Time{wall.Add(-48 * time.Hour), wall.Add(48 * time.Hour)} {
    47			_, offset := probe.In(loc).Zone()
    48			t := wall.Add(-time.Duration(offset) * time.Second)
    49			if l := t.In(loc); l.Hour() == wall.Hour() && l.Minute() == wall.Minute() && l.Day() == wall.Day() && (first.IsZero() || t.Before(first)) {
    50				first = t
    51			}
    52		}
    53		if first.IsZero() {
    54			_, offset := wall.Add(-48 * time.Hour).In(loc).Zone()
    55			first, _ = wall.Add(-time.Duration(offset) * time.Second).In(loc).ZoneBounds()
    56		}
    57		return first
    58	}
    59	func Offset(zone string, now time.Time) (int, error) {
    60		loc, e := time.LoadLocation(zone)
    61		if e != nil {
    62			return 0, e
    63		}
    64		_, offset := now.In(loc).Zone()
    65		return offset, nil
    66	}
    67	func Fire(s *store.Store, now time.Time) error {
    68		rows, e := s.Rows(`SELECT id FROM schedules WHERE enabled AND next_run_at <= $1 ORDER BY id`, now)
    69		if e != nil {
    70			return e
    71		}
    72		for _, r := range rows {
    73			if e = fireOne(s, r["id"], now); e != nil {
    74				return e
    75			}
    76		}
    77		return nil
    78	}
    79	func fireOne(s *store.Store, id any, now time.Time) error {
    80		tx, e := s.DB.Begin()
    81		if e != nil {
    82			return e
    83		}
    84		defer tx.Rollback()
    85		var q, ns int64
    86		var kind, expression, zone string
    87		var payload []byte
    88		var due time.Time
    89		e = tx.QueryRow(`SELECT queue_id,namespace_id,kind,payload,cron,timezone,next_run_at FROM schedules WHERE id=$1 AND enabled AND next_run_at <= $2 FOR UPDATE`, id, now).Scan(&q, &ns, &kind, &payload, &expression, &zone, &due)
    90		if e == sql.ErrNoRows {
    91			return nil
    92		}
    93		if e != nil {
    94			return e
    95		}
    96		var paused bool
    97		var max int
    98		e = tx.QueryRow(`SELECT paused,max_attempts FROM queues WHERE id=$1`, q).Scan(&paused, &max)
    99		if e != nil {
   100			return e
   101		}
   102		next, e := Next(expression, zone, 0, now)
   103		if e != nil {
   104			return e
   105		}
   106		if !next.After(now) {
   107			return fmt.Errorf("schedule cannot advance")
   108		}
   109		// Advance even while paused. At most one due execution can catch up after downtime.
   110		if !paused {
   111			_, e = tx.Exec(`INSERT INTO jobs(queue_id,namespace_id,kind,payload,priority,state,run_at,max_attempts,created_at,event_at) VALUES($1,$2,$3,$4,5,'queued',$5,$6,$7,$7)`, q, ns, kind, string(payload), due, max, now)
   112			if e != nil {
   113				return e
   114			}
   115		}
   116		_, e = tx.Exec(`UPDATE schedules SET next_run_at=$2,last_run_at=CASE WHEN $3 THEN last_run_at ELSE $4 END WHERE id=$1`, id, next, paused, due)
   117		if e != nil {
   118			return e
   119		}
   120		return tx.Commit()
   121	}
