202	// JSON strings and object keys can contain NUL; PostgreSQL jsonb cannot.
203	func containsNUL(v any) bool {
204		switch x := v.(type) {
205		case string:
206			return strings.ContainsRune(x, 0)
207		case []any:
208			for _, value := range x {
209				if containsNUL(value) {
210					return true
211				}
212			}
213		case map[string]any:
214			for key, value := range x {
215				if strings.ContainsRune(key, 0) || containsNUL(value) {
216					return true
217				}
218			}
219		}
220		return false
221	}
